for name,change in CHANGES.items():
 p=Path(name)
 current=p.read_text() if p.exists() else ''
 digest=hashlib.sha256(current.encode()).hexdigest() if p.exists() else None
 assert digest==change['before'], ('input source mismatch',name)
 for start,end,text in reversed(change['edits']):current=current[:start]+text+current[end:]
 assert hashlib.sha256(current.encode()).hexdigest()==change['after'], ('output source mismatch',name)
 p.parent.mkdir(parents=True,exist_ok=True);p.write_text(current)
